with ranked as (select id, amount, paid_at from payments qualify row_number() over (partition by method order by paid_at desc, id) = 1) select date_trunc('quarter', paid_at) as quarter_start, date_trunc('month', paid_at) as activity_month, approx_percentile(amount, array(0.25, 0.5, 0.75)) as amount_quartiles, count(*) as row_count, count(*) as row_count_2, approx_percentile(amount, 0.5) as amount_p50, min(paid_at) as started_at, max(paid_at) as last_paid_at from ranked group by quarter_start, activity_month order by activity_month
